#include <vector>
#include <algorithm>

std::vector<int> zahlen = {3, 1, 2};
zahlen.push_back(4);              // {3,1,2,4}
zahlen.insert(zahlen.begin(), 0); // {0,3,1,2,4}
std::sort(zahlen.begin(), zahlen.end());  // {0,1,2,3}
std::cout << zahlen.size();       // 4
std::cout << zahlen[0];           // 0
std::cout << zahlen.at(1);        // 1 (prüft Grenzen)

